'use strict';
const commsState={payload:null,customerId:'',campaignId:'',page:0,draft:null};
const commsButton=(label,action,kind='')=>button(label,'x-comms-'+action,kind).replace('<button ','<button type="button" ');
const commsPost=(action,body)=>api('/api/crm/communications/'+action,{method:'POST',body:JSON.stringify(body)});
const commsStatuses={draft:'Preparado',sending:'Enviando',accepted:'Aceptado por proveedor',delivered:'Entregado',read:'Leído en WhatsApp',received:'Recibido',failed:'Falló',uncertain:'Resultado incierto',cancelled:'Descartado'};
const oldCommsTabs=crmTabs;crmTabs=function(){return oldCommsTabs().replace('</div>',`<button class="btn ${crmState.tab==='communications'?'primary':''}" data-action="x-comms-open" aria-pressed="${crmState.tab==='communications'}">Comunicaciones</button></div>`);};
function commsView(r){return `<section class="card"><div class="card-head"><div><h2>Conversaciones, con contexto.</h2><small>Correo y WhatsApp · revisión individual antes de cada envío.</small></div><div class="row">${isSuper()?commsButton('Configurar canales','config','primary'):''}${commsButton('Actualizar','refresh','text')}</div></div><div class="card-body"><div class="row"><span class="comms-status">Correo · ${r.channels.email?'Activo':'Sin activar'}</span><span class="comms-status">WhatsApp · ${r.channels.whatsapp?'Activo':'Sin activar'}</span><span class="comms-status">Google Calendar · ${r.calendar.connected?'Conectado':'Sin conectar'}</span></div><p class="muted">Aceptado por el proveedor no significa entregado. Las confirmaciones llegan por webhooks verificados. Los recordatorios internos no envían mensajes automáticamente.</p>${commsState.customerId||commsState.campaignId?`<p>Vista filtrada ${commsButton('Ver toda la bandeja','clear','text')}</p>`:''}</div></section><div class="kpis crm-kpis crm-spacing">${kpi('Preparados',r.stats.draft,'Pendientes de revisión',true)+kpi('Aceptados',r.stats.accepted,'Sin confirmación de entrega')+kpi('Entregados / leídos',r.stats.delivered+r.stats.read,'Confirmados por el proveedor')+kpi('Recibidos',r.stats.inbound,'Respuestas y conversaciones')}</div><section class="card"><div class="card-head"><div><h2>Bandeja de comunicaciones</h2><small>Prepara un mensaje desde la ficha del cliente o desde una campaña.</small></div></div>${r.items.length?table(['Cliente / destinatario','Mensaje','Canal y estado',''],r.items.map(m=>`<tr><td><strong>${esc(m.customerName||(!m.customerId?'Sin asociar':'Cliente asociado'))}</strong><small>${esc(m.destination)}</small><small>${fmtDate(m.createdAt)} · ${m.direction==='inbound'?'Entrada':'Salida'}</small></td><td><strong>${esc(m.subject||'Mensaje de WhatsApp')}</strong><small>${esc(m.text.slice(0,140))}</small>${m.campaignId?'<small>Vinculado a campaña</small>':''}</td><td>${esc(m.channel==='email'?'Correo':'WhatsApp')}<small>${esc(commsStatuses[m.status]||m.status)}</small></td><td>${commsButton('Revisar','message-'+m.id,'text')}</td></tr>`)):empty('Tu bandeja comienza aquí.','Prepara un correo desde la ficha de un cliente con autorización comercial.')}</section><div class="row crm-spacing">${commsState.page?commsButton('Anterior','prev'):''}${(commsState.page+1)*25<r.total?commsButton('Siguiente','next'):''}<small>${r.total} comunicaciones en tu ámbito</small></div><section class="card card-body crm-spacing"><h2>Tu agenda, también en el calendario.</h2><p>Descarga las actividades pendientes para importarlas en tu calendario. En Google puedes publicar cada actividad desde la agenda de Áurea.</p><div class="row">${allowed('crm','exportar')?commsButton('Descargar agenda (.ics)','ics','primary'):''}${commsButton('Ir a agenda','agenda','text')}</div><p class="muted">Sin asistentes ni invitaciones. El calendario recibe título, fecha y referencia interna. Si cambias o cierras una actividad, usa «Calendario» para actualizarla o retirarla de Google.</p></section>`;}
const preCommsLoad=loadCrm;loadCrm=async function(){if(crmState.tab!=='communications'){await preCommsLoad();const target=document.querySelector('#crm-content');if(!target)return;if(crmState.tab==='agenda'&&allowed('crm','exportar'))target.insertAdjacentHTML('afterbegin',`<div class="row crm-spacing">${commsButton('Descargar agenda (.ics)','ics')}</div>`);if(crmState.tab==='marketing'&&marketingState.view==='campaign'){const c=marketingState.payload?.campaign;if(!c)return;target.insertAdjacentHTML('beforeend',`<section class="card card-body crm-spacing"><h3>Comunicaciones de esta campaña</h3><p>Los registros manuales y las confirmaciones de proveedor se consultan por separado.</p>${commsButton('Ver envíos y respuestas','campaign-inbox-'+c.id)}</section>`);if(['email','whatsapp'].includes(c.channel)&&allowed('crm','crear'))for(const m of c.members.filter(m=>!m.blocked&&!['not_interested','opted_out'].includes(m.status))){const history=target.querySelector(`[data-action="x-marketing-member-history-${CSS.escape(m.customerId)}"]`);history?.insertAdjacentHTML('afterend',commsButton('Preparar '+(c.channel==='email'?'correo':'WhatsApp'),'campaign-compose-'+m.customerId,'text'));}}return;}const target=document.querySelector('#crm-content');if(!target)return;try{const r=await api('/api/crm/communications?'+new URLSearchParams({page:commsState.page,customerId:commsState.customerId,campaignId:commsState.campaignId}));if(!target.isConnected)return;commsState.payload=r;target.innerHTML=commsView(r);}catch(e){if(target.isConnected)target.innerHTML=empty('No pudimos abrir las comunicaciones.',e.message,commsButton('Reintentar','refresh'));}};
const preCommsDetail=crmDetail;crmDetail=function(r){return preCommsDetail(r)+`<section class="card card-body crm-spacing"><h2>Una conversación que continúa.</h2><p>El contacto comercial exige autorización registrada y respeta el canal preferido.</p><div class="row">${allowed('crm','crear')?commsButton('Preparar correo','compose-email','primary')+commsButton('Preparar WhatsApp','compose-whatsapp'):''}${commsButton('Ver comunicaciones','customer-inbox-'+r.detail.id,'text')}</div></section>`;};
const preCommsRows=crmTaskRows;crmTaskRows=function(tasks){const holder=document.createElement('div');holder.innerHTML=preCommsRows(tasks);if(allowed('crm','editar')&&allowed('crm','exportar'))tasks.forEach((t,i)=>holder.querySelectorAll('tbody tr')[i]?.lastElementChild?.insertAdjacentHTML('beforeend',commsButton('Calendario','calendar-'+t.id,'text')));return holder.innerHTML;};
async function commsCompose(customerId,channel,campaignId=''){const r=await api('/api/crm/communications?customerId='+encodeURIComponent(customerId));let fields=`<input type="hidden" name="customerId" value="${esc(customerId)}"><input type="hidden" name="channel" value="${esc(channel)}">`;if(campaignId)fields+=`<input type="hidden" name="campaignId" value="${esc(campaignId)}">`;if(channel==='email')fields+=input('Asunto','subject','','text','required maxlength="180"')+'<label class="field"><span>Mensaje</span><textarea name="text" rows="7" maxlength="10000" required></textarea></label>';else{if(!r.template.name||!r.template.text){toast('El superadministrador debe configurar primero una plantilla aprobada en Meta.');return;}fields+=`<p>Plantilla aprobada: <strong>${esc(r.template.name)}</strong></p><p class="comms-text">${esc(r.template.text)}</p>`;const count=Math.max(0,...[...r.template.text.matchAll(/\{\{(\d+)\}\}/g)].map(m=>Number(m[1])));for(let i=1;i<=Math.min(count,10);i++)fields+=input('Valor para {{'+i+'}}','parameter'+i,'','text','required maxlength="1000"');}fields+=`<p class="muted">Se guardará un mensaje preparado con destinatario y contenido fijos. ${r.channels[channel]?'Luego podrás revisar y confirmar el envío.':'El canal aún no está activo; podrás conservar el preparado sin enviarlo.'}</p>`;modal('Preparar '+(channel==='email'?'correo':'WhatsApp'),pForm('comms-compose-form',fields,'Guardar para revisar',`data-request="${crypto.randomUUID()}"`));}
function commsMessage(m){commsState.draft=m;const ready=commsState.payload?.channels?.[m.channel];modal('Revisar comunicación',`<dl class="crm-facts"><div><dt>Destinatario</dt><dd>${esc(m.destination)}</dd></div><div><dt>Canal</dt><dd>${m.channel==='email'?'Correo · Resend':'WhatsApp · Meta'}</dd></div><div><dt>Estado</dt><dd>${esc(commsStatuses[m.status]||m.status)}</dd></div></dl><h3>${esc(m.subject||'Mensaje de WhatsApp')}</h3><p class="comms-text">${esc(m.text)}</p>${m.error?`<p class="form-error">${esc(m.error)}</p>`:''}${m.status==='uncertain'?'<p class="info-strip">El proveedor puede haber recibido este mensaje. Verifica su panel antes de preparar un nuevo envío; Áurea no lo repetirá.</p>':''}${m.status==='draft'?pForm('comms-send-form',`<p class="muted">Confirmar solicita un envío real al proveedor. Se comprobarán de nuevo la autorización comercial y el destinatario.</p>${ready?'':'<p class="info-strip">Activa primero el canal en la configuración de comunicaciones.</p>'}`,'Confirmar envío',`data-id="${esc(m.id)}"`)+ (allowed('crm','eliminar')?commsButton('Descartar preparado','discard-'+m.id,'text'):''):''}${!m.customerId&&m.direction==='inbound'&&allowed('crm','editar')?commsButton('Asociar a cliente','associate-'+m.id):''}`);const send=document.querySelector('#comms-send-form button[type=submit]');if(send&&!ready)send.disabled=true;}
function commsConfiguration(r){const cards=[['email','Correo · Resend',[['from','Remitente verificado','text'],['replyTo','Correo para respuestas (opcional)','email'],['apiKey','Clave API de Resend','password'],['webhookSecret','Secreto de webhook de Resend (Svix)','password']]],['whatsapp','WhatsApp · Meta Cloud',[['version','Versión Graph habilitada en Meta (vXX.0)','text'],['phoneId','Phone number ID','text'],['countryPrefix','Indicativo por defecto (Colombia: 57)','text'],['accessToken','Token de acceso','password'],['appSecret','App secret para verificar webhooks','password'],['verifyToken','Token de verificación del webhook','password'],['templateName','Nombre exacto de plantilla aprobada','text'],['templateLanguage','Idioma de plantilla (ej.: es_CO)','text'],['templateText','Texto exacto aprobado con {{1}}, {{2}}…','text']]],['calendar','Google Calendar',[['clientId','Client ID de OAuth','text'],['clientSecret','Client secret de OAuth','password'],['redirectUri','URL de retorno de OAuth','url'],['calendarId','Calendar ID (vacío: primary)','text']]]];modal('Configuración de comunicaciones',`<p>Solo superadministrador. Las claves se cifran en el servidor y nunca se muestran aquí. Un campo protegido vacío conserva la clave guardada.</p><p class="muted">Necesitas tus cuentas de Meta, Resend o Google. Para recibir respuestas y entregas, configura HTTPS público y los webhooks indicados. Las cuentas todavía no están activadas.</p>${cards.map(([p,title,inputs])=>{const c=r.connections[p];return `<details class="comms-config"><summary>${title} · ${p==='calendar'?(c.hasRefreshToken?'Conectado':'Sin conectar'):(c.enabled?'Activo':'Desactivado')}</summary>${p!=='calendar'?`<p class="muted">Webhook: ${esc(location.origin+'/api/crm/webhooks/'+p)}</p>`:'<p class="muted">Retorno: /api/crm/communications/calendar/callback · Calendario de cuenta compartida, sin invitados.</p>'}${pForm('comms-config-'+p,(p!=='calendar'?select('Estado del canal','enabled',[['false','Desactivado'],['true','Activo']],String(c.enabled)):'' )+inputs.map(([k,label,type])=>input(label+(type==='password'&&c['has'+k[0].toUpperCase()+k.slice(1)]?' · guardada':''),k,type==='password'?'':c[k]||'',type,`maxlength="${k==='templateText'?10000:2000}" ${type==='password'?'autocomplete="new-password"':''}`)).join('')+'<p class="muted">Guardar no realiza envíos ni comprueba tus credenciales con el proveedor.</p>','Guardar conector',`data-provider="${p}"`)}${p==='calendar'?`<div class="row">${commsButton('Conectar cuenta de Google','google-connect','primary')}${c.hasRefreshToken?commsButton('Desconectar en Áurea','google-disconnect','text'):''}</div><p class="muted">Desconectar detiene el acceso local. Los eventos ya publicados permanecen en Google; retíralos antes si lo necesitas.</p>`:''}</details>`;}).join('')}<p class="muted">Respalda también la clave local crm-integrations.key por separado de la base cifrada. Consulta CRM-INTEGRACIONES.md para activación y recuperación.</p>`);}
const preCommsAction=extraUI.action;extraUI.action=async function(a,t){if(!a.startsWith('x-comms-'))return preCommsAction(a,t);const x=a.slice(8);if(['open','clear'].includes(x)){commsState.customerId='';commsState.campaignId='';commsState.page=0;crmState.tab='communications';if(appState.route!=='crm')go('crm');else render();return;}if(x==='refresh')return loadCrm();if(x==='next'||x==='prev'){commsState.page=Math.max(0,commsState.page+(x==='next'?1:-1));return loadCrm();}if(x==='config'){const r=await api('/api/crm/communications');commsState.payload=r;return commsConfiguration(r);}if(x.startsWith('message-'))return commsMessage(commsState.payload.items.find(m=>m.id===x.slice(8)));if(x.startsWith('compose-'))return commsCompose(crmState.payload.detail.id,x.slice(8));if(x.startsWith('campaign-compose-'))return commsCompose(x.slice(17),marketingState.payload.campaign.channel,marketingState.payload.campaign.id);if(x.startsWith('customer-inbox-')||x.startsWith('campaign-inbox-')){commsState.customerId=x.startsWith('customer-')?x.slice(15):'';commsState.campaignId=x.startsWith('campaign-')?x.slice(15):'';commsState.page=0;crmState.tab='communications';return render();}if(x==='agenda'){crmState.tab='agenda';return render();}if(x==='ics'){const end=new Date(appState.today+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+90);return modal('Exportar agenda a calendario',pForm('comms-ics-form',input('Desde','start',appState.today,'date','required')+input('Hasta','end',end.toISOString().slice(0,10),'date','required')+'<p class="muted">Actividades pendientes de tu ámbito. Sin contactos personales. Hasta 366 días. Es una copia; vuelve a exportar para reflejar cambios.</p>','Descargar .ics'));}if(x.startsWith('calendar-')){const taskId=x.slice(9),r=await commsPost('calendar/review',{taskId});modal('Publicar actividad en Google Calendar',pForm('comms-calendar-form',`<h3>${esc(r.title)}</h3><p>${esc(r.start.date||r.start.dateTime)} · ${esc(r.status)}</p><p>${esc(r.privacy)}</p><p class="muted">${r.connected?'Al confirmar se publicará o actualizará este evento. Si está cerrada, se retirará de Google.':'Google todavía no está conectado. El superadministrador puede configurarlo; mientras tanto, descarga la agenda .ics.'}</p>${r.published?select('Acción','remove',[['false','Actualizar según Áurea'],['true','Retirar de Google sin borrar la actividad']],'false'):''}`,'Confirmar publicación',`data-task="${esc(taskId)}"`));if(!r.connected)document.querySelector('#comms-calendar-form button[type=submit]').disabled=true;return;}if(x==='google-connect'){const r=await commsPost('calendar/connect',{});location.assign(r.url);return;}if(x==='google-disconnect')return modal('Desconectar Google en Áurea',pForm('comms-disconnect-form','<p>Se eliminará la autorización local. Los eventos existentes seguirán en Google. Puedes revocar además el acceso en tu cuenta de Google.</p>','Desconectar'));if(x.startsWith('discard-'))return modal('Descartar mensaje preparado',pForm('comms-discard-form','<p>El mensaje quedará descartado y no podrá enviarse.</p>','Descartar',`data-id="${esc(x.slice(8))}"`));if(x.startsWith('associate-')){const r=await api('/api/crm?query=&page=0');return modal('Asociar mensaje a un cliente',pForm('comms-associate-form',select('Cliente existente','customerId',r.customers.map(c=>[c.id,c.name]),'')+'<p class="muted">Comprueba la identidad del remitente. Asociar no registra autorización comercial.</p>','Asociar',`data-id="${esc(x.slice(10))}"`));}};
const preCommsSubmit=extraUI.submit;extraUI.submit=async function(form,v){if(!form.id.startsWith('comms-'))return preCommsSubmit(form,v);if(form.id==='comms-compose-form'){const parameters=Object.keys(v).filter(k=>/^parameter\d+$/.test(k)).sort((a,b)=>Number(a.slice(9))-Number(b.slice(9))).map(k=>v[k]),m=await commsPost('draft',{...v,parameters,requestKey:form.dataset.request});commsState.customerId=v.customerId;commsState.campaignId='';crmState.tab='communications';closeModal();await loadCrm();return commsMessage(m);}if(form.id.startsWith('comms-config-')){await commsPost('config',{...v,provider:form.dataset.provider,...(v.enabled===undefined?{}:{enabled:v.enabled==='true'})});const r=await api('/api/crm/communications');commsState.payload=r;commsConfiguration(r);toast('Conector guardado.');return null;}if(form.id==='comms-ics-form'){const response=await fetch('/api/crm/calendar.ics?'+new URLSearchParams(v),{credentials:'same-origin'});if(!response.ok){const r=await response.json();throw Error(r.error);}const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download='aurea-agenda.ics';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);closeModal();return null;}let action,body;if(form.id==='comms-send-form'){action='send';body={id:form.dataset.id,confirmation:'ENVIAR'};}if(form.id==='comms-calendar-form'){action='calendar/publish';body={taskId:form.dataset.task,confirmation:'PUBLICAR',remove:v.remove==='true'};}if(form.id==='comms-disconnect-form'){action='calendar/disconnect';body={};}if(form.id==='comms-discard-form'){action='cancel';body={id:form.dataset.id};}if(form.id==='comms-associate-form'){action='associate';body={id:form.dataset.id,customerId:v.customerId};}if(action){const r=await commsPost(action,body);closeModal();await loadCrm();if(action==='send')commsMessage(r);else toast('Cambios guardados.');}return null;};
const preCommsModal=extraUI.modal;extraUI.modal=function(){preCommsModal?.();document.querySelectorAll('[id^="comms-config-"] [data-action^="x-generate-"]').forEach(b=>b.remove());const form=document.querySelector('#crm-task-form');if(form&&!form.elements.time){const task=crmState.payload?.detail?.tasks.find(t=>t.id===form.dataset.id);form.querySelector('.form-error').insertAdjacentHTML('beforebegin',`<div class="form-grid">${input('Hora en Bogotá (opcional)','time',task?.time||'','time')+input('Duración en minutos','durationMinutes',task?.durationMinutes||30,'number','min="15" max="480" step="1" required')}</div><p class="muted">Sin hora, se exporta como evento de todo el día.</p>`);}};
const preCommsDecorate=extraUI.decorate;extraUI.decorate=function(){preCommsDecorate();if(appState.route==='config'&&isSuper()&&!document.querySelector('#comms-settings-shortcut'))document.querySelector('#main')?.insertAdjacentHTML('beforeend',`<section id="comms-settings-shortcut" class="card card-body crm-spacing"><h2>Comunicaciones del CRM</h2><p>Configura correo, WhatsApp y calendario con credenciales protegidas.</p>${commsButton('Configurar canales del CRM','config','primary')}</section>`);};
